effect.shader:
void main() {
vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
vec3 col = texColor.rgb;
col.r = pow(max(col.r, 0.0), redGamma);
col.g = pow(max(col.g, 0.0), greenGamma);
col.b = pow(max(col.b, 0.0), blueGamma);
col = (col - 0.5) * masterContrast + 0.5;
col = clamp(col, 0.0, 1.0);
gl_FragColor = vec4(col, texColor.a);
}
